// lo que dice un proveedor de inicio de sesión que nombra su nube o su marca vive en su archivo (auth-providers/, la
// regla del núcleo sin nube): cada uno exporta su `TEXTOS` con la misma forma, y la tabla los suma
for (const f of require('fs').readdirSync(require('path').join(__dirname, 'auth-providers')).filter((x) => /^[a-z][a-z0-9-]*\.js$/.test(x)).sort()) {
  const propios = require(require('path').join(__dirname, 'auth-providers', f)).TEXTOS;
  if (propios && typeof propios === 'object') for (const [k, v] of Object.entries(propios)) { if (TEXTOS[k]) throw new Error(`texts.js: la clave «${k}» está dos veces`); TEXTOS[k] = v; }
}

// lo que dice el armado del pedido de Configuración (scripts/lib/repo-proposal.js, `rp.*`) vive en ese archivo, que nombra
// las plataformas: la tabla también lo suma
for (const [k, v] of Object.entries(require('../lib/repo-proposal.js').TEXTOS || {})) { if (TEXTOS[k]) throw new Error(`texts.js: la clave «${k}» está dos veces`); TEXTOS[k] = v; }

/** Los valores con nombre de un texto, ordenados: `{n}`, `{fecha}`. */
function valoresDe(texto) {
  return [...new Set([...String(texto || '').matchAll(/\{([A-Za-z][A-Za-z0-9_]*)\}/g)].map((m) => m[1]))].sort();
}

/** Lo que está mal en una tabla: cada problema nombra su clave. Vacío = bien. */
function problemasDeLaTabla(tabla) {
  const out = [];
  for (const [k, v] of Object.entries(tabla || {})) {
    if (!v || typeof v !== 'object') { out.push(`${k}: no es { es, en }`); continue; }
    for (const i of IDIOMAS) {
      if (typeof v[i] !== 'string' || !v[i].trim()) out.push(`${k}: falta el texto en «${i}»`);
      else if (v[i].includes('<')) out.push(`${k}: el texto en «${i}» trae HTML`);
    }
    for (const i of Object.keys(v)) if (!IDIOMAS.includes(i)) out.push(`${k}: idioma desconocido «${i}»`);
    if (typeof v.es === 'string' && typeof v.en === 'string' && valoresDe(v.es).join(',') !== valoresDe(v.en).join(',')) out.push(`${k}: los valores con nombre no son los mismos en los dos idiomas (${valoresDe(v.es).join(', ') || 'ninguno'} / ${valoresDe(v.en).join(', ') || 'ninguno'})`);
  }
  return out;
}

/**
 * El texto de una clave en un idioma, con sus valores. Un idioma desconocido cae a castellano; una clave que no está
 * en la tabla tira (una errata no sale en blanco a la pantalla).
 */
function t(idioma, clave, valores = {}) {
  const e = TEXTOS[clave];
  if (!e) throw new Error(`texts.js: no hay texto para la clave «${clave}»`);
  const s = e[IDIOMAS.includes(idioma) ? idioma : POR_DEFECTO];
  return s.replace(/\{([A-Za-z][A-Za-z0-9_]*)\}/g, (m, n) => (Object.prototype.hasOwnProperty.call(valores, n) ? String(valores[n]) : m));
}

/**
 * Los mensajes que arma el servidor de Configuración (`config.*`, `org.*`) se arman en castellano —así los guarda el
 * caché de la pestaña y los lee la página local— y se dicen en el idioma del pedido al salir: cada clave es un molde
 * (`{rel} no se pudo leer ({codigo})`) que reconoce su texto y devuelve el del otro idioma con los mismos valores. Un
 * valor que es a su vez un mensaje de la casa se traduce igual; lo que no es de la casa (lo que dice un lector del
 * arnés, el nombre de un archivo) pasa tal cual.
 */
const MOLDES = new Map();
function moldesDe(prefijos) {
  const k = prefijos.join('|');
  if (!MOLDES.has(k)) {
    const lista = [];
    for (const [clave, v] of Object.entries(TEXTOS)) {
      if (!prefijos.some((p) => clave.startsWith(p))) continue;
      const nombres = [];
      const fuente = v.es.split(/(\{[A-Za-z][A-Za-z0-9_]*\})/).map((parte) => {
        const m = /^\{([A-Za-z][A-Za-z0-9_]*)\}$/.exec(parte);
        if (m) { nombres.push(m[1]); return '([\\s\\S]*?)'; }
        return parte.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
      }).join('');
      // los moldes con más texto fijo van primero: «{x}: se corrige a mano» no le gana a uno que dice más
      lista.push({ clave, nombres, rx: new RegExp(`^${fuente}$`), fijo: v.es.replace(/\{[A-Za-z][A-Za-z0-9_]*\}/g, '').length });
    }
    lista.sort((a, b) => b.fijo - a.fijo);
    MOLDES.set(k, lista);
  }
  return MOLDES.get(k);
}
const PREFIJOS_DEL_SERVIDOR = ['config.', 'org.', 'proveedor.', 'rp.', 'ficha.'];
// un mensaje de la casa es una frase: lo que pasa de este largo no es uno (el texto de un archivo, un dato pegado) y no se
// prueba contra los moldes, que con varios valores retroceden mucho sobre un texto largo y frenarían el proceso
const LARGO_MAXIMO = 2000;
// los valores de un molde que pueden ser, a su vez, un mensaje de la casa; los demás (un archivo, una ruta, lo que dice
// un lector) son datos y pasan tal cual
const VALORES_QUE_SON_MENSAJES = new Set(['motivo', 'ojo', 'tipo', 'pantalla']);
function traducirMensaje(idioma, texto, prefijos = PREFIJOS_DEL_SERVIDOR, hondura = 0) {
  if (idioma === POR_DEFECTO || !IDIOMAS.includes(idioma) || typeof texto !== 'string' || !texto || texto.length > LARGO_MAXIMO || hondura > 4) return texto;
  for (const m of moldesDe(prefijos)) {
    const r = m.rx.exec(texto);
    if (!r) continue;
    const valores = {};
    m.nombres.forEach((n, i) => { valores[n] = VALORES_QUE_SON_MENSAJES.has(n) ? traducirMensaje(idioma, r[i + 1], prefijos, hondura + 1) : r[i + 1]; });
    return t(idioma, m.clave, valores);
  }
  return texto;
}
// las claves de una respuesta de Configuración que llevan un mensaje de la casa. Todo lo demás es dato de la organización
// (el nombre de una máquina, una persona, un producto) y no se toca aunque coincida con un molde (decisión 6)
const CLAVES_CON_MENSAJE = new Set(['message', 'motivo', 'falta', 'advertencia', 'aviso', 'texto', 'diaTexto', 'tipo', 'migracion', 'ultimoBueno',
  'vencido', 'proyecto', 'pedidos', 'motivoHoy', 'motivoAplicar', 'productosMotivo', 'versionesMotivo',
  // el título y el para qué de cada ficha del tablero que se puede ocultar
  'titulo', 'paraQue']);
/** Una respuesta entera (un objeto JSON): cada mensaje de la casa, en el idioma pedido. */
function traducirRespuesta(idioma, valor, prefijos = PREFIJOS_DEL_SERVIDOR) {
  if (idioma === POR_DEFECTO || !IDIOMAS.includes(idioma)) return valor;
  if (Array.isArray(valor)) return valor.map((x) => traducirRespuesta(idioma, x, prefijos));
  if (valor && typeof valor === 'object') {
    const out = {};
    for (const [k, v] of Object.entries(valor)) {
      // el texto de un archivo (el de una sección, el que «Revisar» validó) termina con un salto: es del archivo
      if (typeof v === 'string') out[k] = CLAVES_CON_MENSAJE.has(k) && !v.includes('\n') ? traducirMensaje(idioma, v, prefijos) : v;
      else out[k] = k === 'borrador' || k === 'oid' ? v : traducirRespuesta(idioma, v, prefijos);
    }
    return out;
  }
  return valor;
}

/** Los textos con un prefijo, en un idioma: `{ clave sin el prefijo: texto }` (para el código de pantalla). */
function textosCon(idioma, prefijo) {
  const out = {};
  for (const k of Object.keys(TEXTOS)) if (k.startsWith(prefijo)) out[k.slice(prefijo.length)] = t(idioma, k);
  return out;
}

module.exports = { IDIOMAS, POR_DEFECTO, TEXTOS, t, valoresDe, problemasDeLaTabla, textosCon, traducirMensaje, traducirRespuesta };
